begin;
update public.lessons
set content = jsonb_set(content, '{phase_two_production}', $p${"production_version": "2.3-owner-review-2026-10-10", "approval_status": "founder_review_not_published", "curriculum_version": "2.0", "lesson_id": "2.3", "primary_media": "audio", "title": "Verify and revise with CLEAR", "learner_promise": "Review your Lesson 2.2 communication with CLEAR, verify an important claim, and retain a useful revision with its human approval status and remaining limits.", "pacing": [{"key": "teaching", "label": "Personal CLEAR review and evidence standards", "minutes": 15}, {"key": "worked_case", "label": "Unsupported commitment, critique and source check", "minutes": 10}, {"key": "application", "label": "Review, verify and revise your communication", "minutes": 25}, {"key": "verification", "label": "Applied correction and human approval evidence", "minutes": 10}], "outcomes": ["Apply Correct, Listener, Enough, Appropriate and Responsible to the saved draft.", "Compare your own review with AI critique and explain a decision about a suggestion.", "Verify a material claim against an authoritative source or approved record.", "Revise unsupported facts, audience tone and a missing next action.", "Record the source and check date, human approval status and remaining limits."], "teaching": [{"heading": "Review personally before asking for critique", "paragraphs": ["Read your Lesson 2.2 draft beside its intended purpose and audience. Under every CLEAR category, name a finding and a reason. Correct checks facts and instructions; Listener checks audience fit; Enough checks gaps and repetition; Appropriate checks tone and setting; Responsible checks privacy, fairness, risk, authority and accountability.", "Separate an attractive sentence from a supported claim. Mark approvals, dates and promises that could change a decision. Check whether the reader can act without guessing."], "think_prompt": "Which sentence needs evidence, and which sentence leaves the recipient unsure what to do?"}, {"heading": "Use critique as additional input", "paragraphs": ["Ask your own AI assistant to examine the same five categories using only authorized material. Compare its suggestions with your personal findings. Accept, revise or reject each important suggestion with a reason.", "A model reviewing its own output is not independent evidence. Agreement from another model also does not establish an internal promise. Check the actual source."], "think_prompt": "What did the AI critique catch or miss, and would any suggested wording change the factual meaning?"}, {"heading": "Check an exact material claim", "paragraphs": ["Write the exact claim and identify a source with authority over it. Compare scope, conditions, version and exceptions. Record the source and the actual check date. Protect private records by saving only an authorized citation or necessary extract.", "A five-day delivery promise requires confirmed capacity for that job. A general statement about typical delivery cannot supply that approval. Verify, qualify accurately or remove an uncertain claim."], "think_prompt": "Does your source support the exact promise, or only a different outcome or condition?"}, {"heading": "Revise and retain the approval boundary", "paragraphs": ["Correct the unsupported meaning, audience tone and missing action. Recheck all five CLEAR categories after editing. Name the person with authority to approve wording and any commitments.", "Obtain human approval before real use. If approval remains pending, retain a reviewed draft awaiting approval. Label fictional approval routes as simulated. Save the before version, checks, revision and limits in Prompt and Communication Evidence."], "think_prompt": "Who can approve the communication, and what still prevents it from being treated as approved?"}], "worked_case": {"label": "A polished proposal promises capacity that has not been confirmed", "setup": "FICTIONAL TRAINING EXAMPLE: “Your estimate is approved; delivery is guaranteed in five days. Supply the outstanding specifications immediately.” The fictional intake record confirms only review within two business days after complete inputs arrive. Room dimensions and a preferred appointment date are missing. Appointment booking requires the scheduling owner’s approval. Estimate approval and delivery capacity are not confirmed.", "evidence_table": [{"claim": "Your estimate is approved.", "evidence": "The fictional record shows an incomplete request; no estimate approval is supplied.", "action": "Remove the invented approval and state the review stage accurately."}, {"claim": "Delivery is guaranteed in five days.", "evidence": "Capacity has not been confirmed. The record provides a review period only.", "action": "Remove the delivery promise. Changing guaranteed to expected does not verify it."}, {"claim": "Supply the outstanding specifications immediately.", "evidence": "Room dimensions and a preferred appointment date are the missing details; no urgent deadline is authorized.", "action": "Request both in plain, respectful language without invented urgency."}, {"claim": "AI says this version is verified and approved.", "evidence": "AI critique is additional input. The source check and authorized human approval are separate actions.", "action": "Record independent source evidence and the actual human approval status."}], "revised_example": "Thank you for your estimate request. Please reply with the room dimensions and your preferred appointment date. After we receive complete information, our team will review your request within two business days. We will confirm the estimate and schedule after the appropriate review. No appointment or delivery date is confirmed by this message.", "demonstration_steps": ["Apply all five CLEAR questions", "Compare critique without treating it as proof", "Check the claim against its source", "Revise and preserve the approval boundary"], "question": "Which correction fixes the unsupported commitment, which helps the customer act, and who may approve the final message?"}, "application": [{"heading": "Review the saved communication yourself", "minutes": 7, "instruction": "Continue with the same project and Lesson 2.2 communication. Record one finding and reason under each CLEAR category before asking AI. Identify the recipient action and material claims.", "evidence": "Original draft, audience and five personal CLEAR findings."}, {"heading": "Compare critique and verify a claim", "minutes": 10, "instruction": "Use the approved request with your own AI assistant and authorized source material. Compare its critique with your judgment. Verify at least one exact material claim against an authoritative source or approved record; record source, version or date, actual check date and result.", "evidence": "AI critique, decision about a suggestion and independent claim-check evidence."}, {"heading": "Revise and identify the approval route", "minutes": 8, "instruction": "Correct the draft and explain useful changes. Obtain approval before real use; mark pending approval accurately. Save the original, revised communication, approval status and remaining limits. Complete the fictional applied correction without sending a message.", "evidence": "Revision, rationale, authorized approver, actual status and applied correction."}], "approved_ai_request": "Critique this draft under Correct, Listener, Enough, Appropriate and Responsible. Flag unsupported claims and missing information. Do not assert that facts are verified. Draft and approved sources: [inputs].", "responsibility_map_fields": ["Purpose, recipient and intended action", "AI critique role and limits", "Exact claim and authorized source", "Source date or version and actual check date", "Human reviewer and approval authority", "Remaining limits and decision before real use"], "verification": [{"heading": "Correct all three applied problems", "minutes": 4, "prompt": "Revise the fictional draft containing an invented fact, unsuitable audience tone and missing next action. Explain a correction for each."}, {"heading": "Explain independent verification", "minutes": 3, "prompt": "Show the exact claim, source, check date and result. Explain why AI self-review alone is insufficient."}, {"heading": "Retain approval status and limits", "minutes": 3, "prompt": "Identify the authorized approver. Distinguish actual approval from pending or simulated approval, and save the evidence in your existing Project Record."}], "completion_criteria": ["Personal findings under all five CLEAR categories", "AI critique compared with your own review and a decision explained", "At least one material claim checked against an authoritative source or approved record", "Source identity, available date or version, check date and verification result recorded", "Revised communication with useful changes explained", "Applied correction of invented fact, tone and missing next action", "Human approval status and remaining limits saved without overwriting Lesson 2.2 evidence"], "handoff": "Carry your reviewed communication, source checks and human approval points into Lesson 2.4: Choose Assistants, Automation and Agents. The next lesson opens according to its release schedule.", "editorial_notes": {"status": "Founder-review draft; course, journey and lesson remain unpublished.", "media": "Same approved landscape instructor and voice, four guided teaching chapters and four narrated fictional demonstrations. Founder playback acceptance remains separate.", "source": "ACA_Phase_Two_Six_Week_Curriculum_Master.docx v2.0, October 4 2026, Lesson 2.3.", "example_data": "Estimate request, five-day promise, intake review record and approval roles are fictional teaching data."}}$p$::jsonb, true)
where id='2fb56ed8-e822-4700-afc5-3f61df5855fa' and course_id='3e4a092a-256f-4f09-ad1b-ce63b45319a7'
and journey_id='c6bdc7b0-ba8c-481d-9d89-9d18d71d19bc' and page_id='2.3' and status='draft'
and content->'phase_two'->>'source_version'='2.0'
and not content ? 'phase_two_production'
returning id,page_id,status;
update public.aca_phase_two_workbook_definitions
set content=jsonb_set(content,'{pages}',(content->'pages') || jsonb_build_array($w${"number": 3, "lesson_id": "2.3", "kicker": "JOURNEY TWO / LESSON 2.3", "title": "Verify and Revise with CLEAR", "blocks": [{"type": "heading", "text": "Review personally before asking for critique"}, {"type": "text", "text": "Read your Lesson 2.2 draft beside its intended purpose and audience. Under every CLEAR category, name a finding and a reason. Correct checks facts and instructions; Listener checks audience fit; Enough checks gaps and repetition; Appropriate checks tone and setting; Responsible checks privacy, fairness, risk, authority and accountability."}, {"type": "text", "text": "Separate an attractive sentence from a supported claim. Mark approvals, dates and promises that could change a decision. Check whether the reader can act without guessing."}, {"type": "heading", "text": "Use critique as additional input"}, {"type": "text", "text": "Ask your own AI assistant to examine the same five categories using only authorized material. Compare its suggestions with your personal findings. Accept, revise or reject each important suggestion with a reason."}, {"type": "text", "text": "A model reviewing its own output is not independent evidence. Agreement from another model also does not establish an internal promise. Check the actual source."}, {"type": "heading", "text": "Check an exact material claim"}, {"type": "text", "text": "Write the exact claim and identify a source with authority over it. Compare scope, conditions, version and exceptions. Record the source and the actual check date. Protect private records by saving only an authorized citation or necessary extract."}, {"type": "text", "text": "A five-day delivery promise requires confirmed capacity for that job. A general statement about typical delivery cannot supply that approval. Verify, qualify accurately or remove an uncertain claim."}, {"type": "heading", "text": "Revise and retain the approval boundary"}, {"type": "text", "text": "Correct the unsupported meaning, audience tone and missing action. Recheck all five CLEAR categories after editing. Name the person with authority to approve wording and any commitments."}, {"type": "text", "text": "Obtain human approval before real use. If approval remains pending, retain a reviewed draft awaiting approval. Label fictional approval routes as simulated. Save the before version, checks, revision and limits in Prompt and Communication Evidence."}, {"type": "heading", "text": "A polished proposal promises capacity that has not been confirmed"}, {"type": "text", "text": "FICTIONAL TRAINING EXAMPLE: “Your estimate is approved; delivery is guaranteed in five days. Supply the outstanding specifications immediately.” The fictional intake record confirms only review within two business days after complete inputs arrive. Room dimensions and a preferred appointment date are missing. Appointment booking requires the scheduling owner’s approval. Estimate approval and delivery capacity are not confirmed."}, {"type": "note", "theme": "gold", "title": "Revised fictional example", "text": "Thank you for your estimate request. Please reply with the room dimensions and your preferred appointment date. After we receive complete information, our team will review your request within two business days. We will confirm the estimate and schedule after the appropriate review. No appointment or delivery date is confirmed by this message."}, {"type": "heading", "text": "Practice with your own AI assistant"}, {"type": "note", "theme": "gold", "title": "Approved CLEAR critique request", "text": "Critique this draft under Correct, Listener, Enough, Appropriate and Responsible. Flag unsupported claims and missing information. Do not assert that facts are verified. Draft and approved sources: [inputs]."}, {"type": "field", "id": "p2-j2-3-original", "label": "Communication from Lesson 2.2 to review", "hint": "", "lines": 7}, {"type": "field", "id": "p2-j2-3-audience", "label": "Recipient, purpose and intended next action", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-correct", "label": "Correct — facts, names, dates, numbers and instructions", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-listener", "label": "Listener — does it serve this audience?", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-enough", "label": "Enough — missing detail and unnecessary repetition", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-appropriate", "label": "Appropriate — tone and setting", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-responsible", "label": "Responsible — privacy, fairness, risk, authority and accountability", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-critique", "label": "AI critique (additional input, not verification)", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-comparison", "label": "What did you accept, revise or reject, and why?", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-claim", "label": "Exact material claim you checked", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-source", "label": "Authoritative source or approved record and relevant detail", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-sourceDate", "label": "Source date or version (state unknown if unavailable)", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-checkedDate", "label": "Actual date you checked the source", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-result", "label": "Verification result — supported, contradicted or unresolved, and why", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-revised", "label": "Revised communication", "hint": "", "lines": 7}, {"type": "field", "id": "p2-j2-3-changes", "label": "What changed and why the result is more useful", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-approval", "label": "Authorized human approver and actual approval status (or pending)", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-limits", "label": "Remaining limits and unresolved claims (or explain none remain)", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-3-appliedCheck", "label": "Correct the fictional draft: invented fact, audience tone and missing next action", "hint": "", "lines": 7}, {"type": "field", "id": "p2-j2-3-notes", "label": "Personal study notes and questions", "hint": "", "lines": 6}, {"type": "note", "theme": "gold", "title": "Carry your evidence into Lesson 2.4", "text": "Carry your reviewed communication, source checks and human approval points into Lesson 2.4: Choose Assistants, Automation and Agents. The next lesson opens according to its release schedule."}]}$w$::jsonb),true),
version=version+1,updated_at=now()
where journey_number=2 and version=2
and jsonb_array_length(content->'pages')=2
and not exists(select 1 from jsonb_array_elements(content->'pages') p where p->>'lesson_id'='2.3')
returning journey_number,version,jsonb_array_length(content->'pages') as pages;
